                <div class="input-container col-12 d-flex" title="Banco"><label for="employeename" class="input-title align-self-center">Banco</label><input type="text" id="hiring-employee-bank" class="input-value form-control align-self-center" name="bank" placeholder="Bancolombia"></div>
