            <div class="input-container col-12 d-flex" title="AFP"><label for="employeename" class="input-title align-self-center">AFP</label><div class="crud-input-container input-value" prefix="/admin/afp/"><div class="crud-input-selected-container d-flex justify-content-between" id="hiring-employee-afp"><input type="text" class="crud-current-selected-input align-self-center" placeholder="Compensar"><i class="crud-input-arrow fa-solid fa-chevron-down align-self-center"></i></div><ul class="crud-list closed scrollable"><li class="crud-item-add d-flex justify-content-between"><input type="text" class="crud-item-add-input align-self-center" placeholder="Agregar"><i class="crud-item-add-icon fa-solid fa-plus align-self-center"></i></li></ul></div></div>
            <div class="input-container col-12 d-flex" title="ARL"><label for="employeename" class="input-title align-self-center">ARL</label><div class="crud-input-container input-value" prefix="/admin/arl/"><div class="crud-input-selected-container d-flex justify-content-between" id="hiring-employee-arl"><input type="text" class="crud-current-selected-input align-self-center" placeholder="Coosalud"><i class="crud-input-arrow fa-solid fa-chevron-down align-self-center"></i></div><ul class="crud-list closed scrollable"><li class="crud-item-add d-flex justify-content-between"><input type="text" class="crud-item-add-input align-self-center" placeholder="Agregar"><i class="crud-item-add-icon fa-solid fa-plus align-self-center"></i></li></ul></div></div>
